import React from 'react';

export default function Blobs({ variant = 'default' }) {
  const sets = {
    default: [
      { w:700, h:600, top:'-20%', left:'-20%', bg:'radial-gradient(ellipse, rgba(180,175,165,0.6) 0%, transparent 65%)', anim:'cloudDrift 18s ease-in-out infinite' },
      { w:500, h:450, top:'30%', right:'-15%', bg:'radial-gradient(ellipse, rgba(165,168,178,0.5) 0%, transparent 65%)', anim:'cloudDrift 14s ease-in-out infinite reverse 3s' },
      { w:400, h:380, bottom:'-5%', left:'20%', bg:'radial-gradient(ellipse, rgba(175,170,160,0.4) 0%, transparent 65%)', anim:'cloudDrift 20s ease-in-out infinite 6s' },
    ],
    calm: [
      { w:700, h:550, top:'-15%', left:'-20%', bg:'radial-gradient(ellipse, rgba(165,178,185,0.55) 0%, transparent 65%)', anim:'cloudDrift 16s ease-in-out infinite' },
      { w:500, h:400, bottom:'0', right:'-12%', bg:'radial-gradient(ellipse, rgba(170,175,185,0.45) 0%, transparent 65%)', anim:'cloudDrift 12s ease-in-out infinite reverse' },
    ],
    warm: [
      { w:650, h:520, top:'-10%', right:'-18%', bg:'radial-gradient(ellipse, rgba(185,170,165,0.55) 0%, transparent 65%)', anim:'cloudDrift 15s ease-in-out infinite' },
      { w:450, h:400, bottom:'5%', left:'-10%', bg:'radial-gradient(ellipse, rgba(178,168,160,0.45) 0%, transparent 65%)', anim:'cloudDrift 19s ease-in-out infinite reverse' },
    ],
  };

  return (
    <div style={{ position:'fixed', inset:0, zIndex:0, pointerEvents:'none', overflow:'hidden' }}>
      {(sets[variant]||sets.default).map((b,i) => (
        <div key={i} style={{ position:'absolute', width:b.w, height:b.h, top:b.top, left:b.left, right:b.right, bottom:b.bottom, background:b.bg, filter:'blur(60px)', animation:b.anim }} />
      ))}
      <div style={{ position:'absolute', inset:0, backgroundImage:`url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")`, opacity:0.035 }} />
    </div>
  );
}
